const input=$json.body??$json;
const arr=v=>Array.isArray(v)?v:[];
const truthy=v=>v===true||v==="true"||v===1||v==="1";
const requiredEvidence=arr(input.required_evidence);
const verifiedEvidence=arr(input.verified_evidence);
const milestones=arr(input.milestones);
const blockers=arr(input.blockers);
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const execution=input.execution??{};
const active=truthy(input.closing_active)||truthy(execution.active)||["active","in_progress","closing_active"].includes(String(execution.status||"").toLowerCase());
const evidenceReconciled=truthy(input.evidence_reconciled)||["reconciled","complete","verified"].includes(String(input.evidence_status||"").toLowerCase());
const verifiedIds=new Set(verifiedEvidence.map(e=>String(e.id??e)));
const evidenceComplete=requiredEvidence.length===0||requiredEvidence.every(e=>verifiedIds.has(String(e.id??e)));
const failedEvidence=verifiedEvidence.filter(e=>truthy(e.failed)||["failed","rejected","invalid"].includes(String(e.status||"").toLowerCase()));
const milestonesComplete=milestones.length===0||milestones.every(m=>truthy(m.completed)||["completed","done","verified"].includes(String(m.status||"").toLowerCase()));
const executionIdentity=Boolean(input.execution_id||execution.execution_id||execution.id);
const signedExecuted=truthy(input.executed_agreement)||["executed","signed","fully_executed"].includes(String(input.agreement_status||"").toLowerCase());
const blockersClear=blockers.length===0;
const closingDateValid=Boolean(input.closing_date)&&!Number.isNaN(new Date(input.closing_date).getTime());
const outcomeReady=identityComplete&&active&&evidenceReconciled&&evidenceComplete&&failedEvidence.length===0&&milestonesComplete&&executionIdentity&&signedExecuted&&blockersClear&&closingDateValid;

let status="outcome_confirmation_required",nextWorkflow="WF-282",humanReview=true;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";}
else if(!active){status="closing_not_active";nextWorkflow="WF-279";}
else if(!evidenceReconciled||!evidenceComplete||failedEvidence.length>0){status="evidence_reconciliation_incomplete";nextWorkflow="WF-281";}
else if(!milestonesComplete){status="milestone_completion_incomplete";nextWorkflow="WF-280";}
else if(!executionIdentity||!signedExecuted){status="execution_evidence_missing";nextWorkflow="WF-278";}
else if(!blockersClear||!closingDateValid){status="blocked";nextWorkflow="WF-126";}
else{status="final_closing_outcome_ready";nextWorkflow="WF-283";}

return [{json:{...input,workflow:"WF-282",workflow_name:"Reconciled Closing Evidence → Final Closing Outcome & Completion Controller",status,final_closing_outcome:{identity_complete:identityComplete,closing_active:active,evidence_reconciled:evidenceReconciled,evidence_complete:evidenceComplete,failed_evidence_count:failedEvidence.length,milestones_complete:milestonesComplete,execution_identity_present:executionIdentity,signed_executed:signedExecuted,blockers_clear:blockersClear,closing_date_valid:closingDateValid,ready:outcomeReady},next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:status,audit:{event_type:"reconciled_closing_evidence_final_outcome",idempotency_key:input.idempotency_key||`wf-282:${input.deal_id||"unknown"}:${input.close_id||"none"}:${input.version||1}`}}}];
